PAGES["equities/valuation"] = pg => pendingPage(pg, { lede: "P/E, forward P/E, dividend yield, price-to-book, earnings and revenue growth for every index.", what: "Valuation data is published by index providers or sold by data vendors; no free API covers all 20 indices.", fields: "trailing and forward P/E, dividend yield, P/B, EPS and revenue growth, history", source: "Index provider factsheets (monthly PDFs), MSCI/FTSE country indices, or a licensed feed" });
PAGES["equities/sectors"] = pg => pendingPage(pg, { lede: "Sector weights and performance by index.", what: "Sector data requires constituent-level data.", fields: "sector allocation, sector returns, leaders and laggards, breadth", source: "Constituent lists from index providers; sector ETFs as proxies for the US and Europe" });

