PAGES["currencies/ranking"] = G_(pg => { const st = (GD().fx.strength || []).slice().sort((a, b) => (a.rank || 99) - (b.rank || 99));
  return header(pg, "Each currency's average change against the other eight, by window, combined into one score.") + metaStrip(["yahoo"]) +
    panel("Currency strength ranking", table([{ t: "Rank", n: 1 }, { t: "Currency" }, { t: "1W", n: 1 }, { t: "1M", n: 1 }, { t: "3M", n: 1 }, { t: "1Y", n: 1 }, { t: "Composite", n: 1 }, { t: "Absolute 1Y vs USD", n: 1 }], st.map(s => [s.rank ?? "—", `<a href="#/currencies/detail/${s.ccy}"><b>${s.ccy}</b></a> <span class="dim sm">${esc(s.name)}</span>`, pct(s.scores.w1), pct(s.scores.m1), pct(s.scores.m3), pct(s.scores.y1), `<b class="num">${sgn(s.composite, 2)}</b>`, pct(s.absolute?.y1)]))) + `<div class="note">${esc(GD().fx.note)}</div>`; });
PAGES["currencies/relative"] = G_(pg => { const fx = GD().fx, w = pg.param || "m1";
  return header(pg, "Percentage change of each row currency against each column currency.", { right: selector(pg, [["w1", "1 week"], ["m1", "1 month"], ["m3", "3 months"], ["y1", "1 year"]], w, "Window") }) + metaStrip(["yahoo"]) +
    panel(`Relative strength, ${({ w1: "1 week", m1: "1 month", m3: "3 months", y1: "1 year" })[w]}`, matrixHeat(fx.currencies, fx.currencies, fx.relative[w] || [], { scale: w === "y1" ? 15 : w === "m3" ? 8 : 4, fmt: v => fmt(v, 1), left: 60, top: 40 })) + `<div class="note">Blue: the row currency gained against the column currency. Read across a row to see where a currency is strong or weak.</div>`; });
PAGES["currencies/detail"] = G_(pg => { const fx = GD().fx, c = (pg.param || "EUR").toUpperCase(), s = fx.strength.find(x => x.ccy === c) || fx.strength[0], ck = cBy(Object.entries({ USD: "us", EUR: "de", CNY: "cn", JPY: "jp", GBP: "gb", INR: "in", CAD: "ca", CHF: "ch", RUB: "ru" }).find(([k]) => k === s.ccy)[1]);
  const ser = fx.series[s.ccy];
  return header(pg, `${esc(s.name)} (${esc(s.ccy)}): performance, valuation, rate and inflation differentials, positioning.`, { right: selector(pg, fx.currencies.map(x => [x, x]), s.ccy, "Currency") }) + metaStrip(["yahoo", "bis", "imf", "worldbank", "cftc"]) +
    `<div class="g g6">${kpi("Strength rank", s.rank ? `${s.rank} / 9` : "—", `composite ${sgn(s.composite, 2)}`)}${kpi(s.ccy === "USD" ? "Dollar index" : "US$ per unit", s.absolute ? fmt(s.absolute.last, s.ccy === "USD" ? 2 : 4) : "—", s.absolute ? `1Y ${pct(s.absolute.y1)}` : "")}${kpi("Policy rate", s.policy_rate ? fmt(s.policy_rate.value, 2) + "%" : "—", s.rate_diff_vs_usd != null ? `vs USD ${sgn(s.rate_diff_vs_usd, 2)} pp` : "")}${kpi("Inflation", s.inflation != null ? fmt(s.inflation, 1) + "%" : "—", s.infl_diff_vs_us != null ? `vs US ${sgn(s.infl_diff_vs_us, 1)} pp (IMF, ${GD().year - 1})` : "")}${kpi("Real effective rate", s.reer ? fmt(s.reer.latest, 1) : "—", s.reer ? `1Y ${pct(s.reer.y1)} · vs 10y avg ${pct(s.reer.vs_10y_avg, 1)}` : "BIS")}${kpi("Price level vs US (PPP)", s.ppp_ratio ? fmt(s.ppp_ratio.value, 2) : "—", s.ppp_ratio ? `${s.ppp_ratio.year} · below 1 = cheaper than US` : "")}</div>
    <div class="g g2">${panel(s.ccy === "USD" ? "Dollar index" : `US$ per ${s.ccy}`, ser ? lineChart([{ name: s.ccy, dates: ser.dates, values: ser.values, color: C.gold }], { height: 220, fmt: v => fmt(v, s.ccy === "USD" ? 1 : 4) }) : PEND)}
      ${panel("Effective exchange rates (BIS, broad)", s.reer ? lineChart([{ name: "Real (REER)", dates: s.reer.series.dates, values: s.reer.series.values, color: C.gold }, s.neer && { name: "Nominal (NEER)", dates: s.neer.series.dates, values: s.neer.series.values, color: C.s1 }].filter(Boolean), { height: 220, fmt: v => fmt(v, 0) }) : PEND)}</div>
    <div class="g g2">${panel("Futures positioning (CFTC)", s.cftc ? `<div class="kv" style="display:grid;grid-template-columns:auto 1fr;gap:5px 12px"><span class="dim">Leveraged funds net</span><span class="num">${fmt(s.cftc.lev_net, 0)} contracts (4w ${sgn(s.cftc.lev_4w)})</span><span class="dim">Asset managers net</span><span class="num">${fmt(s.cftc.am_net, 0)}</span><span class="dim">As of</span><span>${esc(s.cftc.date)}</span></div>` + lineChart([{ name: "Leveraged funds net", dates: s.cftc.series.dates, values: s.cftc.series.values, color: C.s2 }], { height: 150, zero: true, fmt: v => fmt(v, 0) }) : `<span class="dim">No CME futures positioning for ${esc(s.ccy)} in the CFTC report.</span>`)}
      ${panel("Central bank intervention and reserves", `${ck ? (() => { const res = wbL("FI.RES.XGLD.CD", ck.iso3); return res ? `<p>FX reserves excluding gold: <b>${big(res.value)}</b> (${res.year}, World Bank).</p>` : ""; })() : ""}<div class="pending"><b>Pending:</b> monthly reserve changes and official intervention disclosures (e.g. Japan MoF, SNB quarterly, RBI weekly) to detect intervention.</div>`)}</div>
    ${ck ? `<div class="note"><a href="#/economies/${ck.key}">${esc(ck.name)} economy →</a></div>` : ""}`; });
PAGES["currencies/valuation"] = G_(pg => { const st = GD().fx.strength;
  return header(pg, "Valuation indicators: purchasing power parity (World Bank) and real effective exchange rates (BIS). Valuation gaps can persist for years; they are not timing signals.") + metaStrip(["worldbank", "bis"]) +
    panel("Valuation table", table([{ t: "Currency" }, { t: "Price level vs US (PPP ratio)", n: 1 }, { t: "Year" }, { t: "REER", n: 1 }, { t: "REER 1Y", n: 1 }, { t: "REER vs 10y avg", n: 1 }, { t: "NEER 1Y", n: 1 }], st.map(s => [`<b>${s.ccy}</b>`, s.ppp_ratio ? `<span class="num">${fmt(s.ppp_ratio.value, 2)}</span>` : "—", s.ppp_ratio?.year ?? "", s.reer ? `<span class="num">${fmt(s.reer.latest, 1)}</span>` : "—", pct(s.reer?.y1), pct(s.reer?.vs_10y_avg, 1), pct(s.neer?.y1)]))) +
    panel("Real effective exchange rates (index)", lineChart(st.filter(s => s.reer).slice(0, 6).map((s, i) => ({ name: s.ccy, dates: s.reer.series.dates, values: s.reer.series.values, color: [C.gold, C.s1, C.s2, C.s3, C.s4, C.s5][i] })), { height: 240, fmt: v => fmt(v, 0) })) +
    `<div class="note">PPP ratio below 1: the local price level is lower than in the US at market exchange rates. REER above its 10-year average: the currency is dearer than usual after inflation.</div>`; });
PAGES["currencies/differentials"] = G_(pg => { const st = GD().fx.strength;
  return header(pg, "Interest rate and inflation differentials against the US. Carry and real-rate gaps are among the main medium-term currency drivers.") + metaStrip(["bis", "imf"]) +
    panel("Differentials vs USD", table([{ t: "Currency" }, { t: "Policy rate", n: 1 }, { t: "Rate diff vs US (pp)", n: 1 }, { t: "Inflation", n: 1 }, { t: "Inflation diff (pp)", n: 1 }, { t: "Real policy rate", n: 1 }, { t: "1Y vs USD", n: 1 }], st.map(s => [`<b>${s.ccy}</b>`, s.policy_rate ? `<span class="num">${fmt(s.policy_rate.value, 2)}%</span>` : "—", `<span class="num">${sgn(s.rate_diff_vs_usd, 2)}</span>`, s.inflation != null ? `<span class="num">${fmt(s.inflation, 1)}%</span>` : "—", `<span class="num">${sgn(s.infl_diff_vs_us, 1)}</span>`, s.policy_rate && s.inflation != null ? `<span class="num">${sgn(s.policy_rate.value - s.inflation, 2)}%</span>` : "—", pct(s.absolute?.y1)]))) +
    `<div class="note">Policy rates: BIS, latest month. Inflation: IMF WEO annual average for ${GD().year - 1} (estimate). Real policy rate = policy rate − inflation; a simple backward-looking measure.</div>`; });
PAGES["currencies/positioning"] = G_(pg => { const st = GD().fx.strength;
  return header(pg, "Speculative positioning in currency futures (CFTC) and realised volatility.") + metaStrip(["cftc", "yahoo"]) +
    panel("Positioning and volatility", table([{ t: "Currency" }, { t: "Leveraged funds net", n: 1 }, { t: "4-week change", n: 1 }, { t: "Asset managers net", n: 1 }, { t: "As of" }, { t: "Vol 30d", n: 1 }], st.map(s => [`<b>${s.ccy}</b>`, s.cftc ? `<span class="num">${fmt(s.cftc.lev_net, 0)}</span>` : `<span class="dim">no CME contract</span>`, s.cftc ? `<span class="num">${sgn(s.cftc.lev_4w)}</span>` : "", s.cftc ? `<span class="num">${fmt(s.cftc.am_net, 0)}</span>` : "", s.cftc ? esc(s.cftc.date) : "", `<span class="num">${fmt(s.vol30, 1)}%</span>`]))) +
    `<div class="note">Contracts on CME; positive = net long the currency against USD. CNY, INR and RUB have no CFTC-reported futures positioning.</div>`; });
PAGES["currencies/asset-matrix"] = G_(pg => { const m = GD().matrix, w = pg.param || "corr250";
  const lab = { corr90: "90-day correlation", corr250: "250-day correlation", beta250: "250-day beta (asset return per 1% currency move)" };
  return header(pg, "How currency moves have related to commodities, equities, bonds and Bitcoin. Statistical relationships change over time and are not causal.", { right: selector(pg, [["corr90", "Corr 90d"], ["corr250", "Corr 250d"], ["beta250", "Beta 250d"]], w, "Measure") }) + metaStrip(["yahoo"]) +
    panel(esc(lab[w]), matrixHeat(m.drivers || [], m.assets || [], m[w] || [], { scale: w === "beta250" ? 2 : 1, fmt: v => fmt(v, 2), left: 120 }), "daily returns, weekdays") +
    (m.scenarios ? panel(`Historical scenarios: dollar index moves (${esc(m.scenarios.sample)})`, table([{ t: "Scenario" }, { t: "Windows", n: 1 }, ...m.assets.map(a => ({ t: a, n: 1 }))], m.scenarios.rows.map(r => [esc(r.bucket), r.n, ...m.assets.map(a => r.assets[a] ? pct(r.assets[a].median, 1) : "—")])) + `<div class="note">Median concurrent 3-month change. ${esc(m.scenarios.note)}</div>`) : "") +
    panel("Rolling 250-day correlation with the dollar index", lineChart(Object.entries(m.rolling_usd || {}).map(([k, v], i) => ({ name: k, dates: v.dates, values: v.values, color: [C.gold, C.s2, C.s3, C.s1][i] })), { height: 220, zero: true, fmt: v => fmt(v, 2) })) +
    `<div class="g g3">${panel("Trade and inflation", `<p class="sm">A weaker currency raises import prices and can lift inflation; it helps exporters' competitiveness with a lag. See <a href="#/relationships/oil-india">Oil → India</a>.</p><div class="pending sm">Pass-through regressions need monthly CPI and trade data (Phase 2).</div>`)}${panel("Corporate profitability", `<p class="sm">Companies with foreign revenue gain from a weaker home currency when translating earnings. See <a href="#/relationships/europe-germany">Europe → German equities</a>.</p>`)}${panel("Emerging markets", `<p class="sm">A strong dollar has tended to coincide with weaker EM assets. The EEM column above measures it.</p>`)}</div>`; });

/* ======================= MODULE 8: COMMODITIES ======================= */
const COM_SRC = { "Energy": "EIA, IEA, OPEC monthly reports; JODI", "Precious metals": "World Gold Council, Silver Institute", "Industrial metals": "USGS, ICSG (copper), IAI (aluminium), worldsteel", "Battery metals": "USGS; LME and benchmark price agencies (licensed)", "Agriculture": "USDA WASDE and FAS, FAO, ICO (coffee), ICAC (cotton)" };
function commodityTable(list) { return table([{ t: "Commodity" }, { t: "Group" }, { t: "Unit" }, { t: "Last", n: 1 }, ...PERF_COLS, { t: "Vol 30d", n: 1 }, { t: "As of" }], list.map(c => c.perf ? [`<a href="#/commodities/detail/${c.key}"><b>${esc(c.name)}</b></a> <span class="sm dim">${esc(c.ticker)}</span>`, esc(c.group), `<span class="sm">${esc(c.unit)}</span>`, `<span class="num">${fmt(c.perf.last, 2)}</span>`, ...perfCells(c.perf), `<span class="num">${fmt(c.perf.vol30, 1)}%</span>`, `<span class="sm dim">${esc(c.perf.date)}</span>`] : [`<b>${esc(c.name)}</b>`, esc(c.group), esc(c.unit), "—", "", "", "", "", "", "", PEND])); }
PAGES["commodities/overview"] = G_(pg => { const cs = GD().markets.commodities;
  return header(pg, "Nineteen commodities across energy, metals and agriculture. Gold has its own deep-dive section.") + metaStrip(["yahoo"]) +
    panel("1-month change (%)", barChart(cs.filter(c => c.perf).map(c => c.name.split(" ")[0]), cs.filter(c => c.perf).map(c => c.perf.m1), { diverging: true, height: 190, unit: "%", fmt: v => fmt(v, 1) })) +
    panel("All commodities", commodityTable(cs), `${cs.filter(c => c.perf).length} of ${cs.length} priced`, "flush") +
    `<div class="note">Uranium, lithium, nickel and cobalt have no free daily futures price here (LME and price-reporting agencies are licensed).</div>`; });
const comGroup = (lab, groups) => G_(pg => header(pg, `${lab}: prices and performance.`) + metaStrip(["yahoo"]) + panel(lab, commodityTable(GD().markets.commodities.filter(c => groups.includes(c.group))), "", "flush") +
  `<div class="g g2" style="margin-top:12px">${GD().markets.commodities.filter(c => groups.includes(c.group) && c.series).slice(0, 4).map(c => panel(esc(c.name), lineChart([{ name: c.name, dates: c.series.dates, values: c.series.values, color: C.gold }], { height: 170 }))).join("")}</div>`);
PAGES["commodities/energy"] = comGroup("Energy", ["Energy"]); PAGES["commodities/metals"] = comGroup("Metals", ["Precious metals", "Industrial metals", "Battery metals"]); PAGES["commodities/agriculture"] = comGroup("Agriculture", ["Agriculture"]);
PAGES["commodities/detail"] = G_(pg => { const cs = GD().markets.commodities, c = cs.find(x => x.key === pg.param) || cs[0], p = c.perf, m = GD().matrix;
  const mi = { gold: "Gold", silver: "Silver", wti: "Oil (WTI)", copper: "Copper" }[c.key], ui = (m.drivers || []).indexOf("USD (DXY)"), ai = (m.assets || []).indexOf(mi);
  const usdCorr = ui >= 0 && ai >= 0 ? m.corr250[ui][ai] : null, usdBeta = ui >= 0 && ai >= 0 ? m.beta250[ui][ai] : null;
  const pend = [["Production", "Supply"], ["Consumption", "Demand"], ["Inventories", "Exchange and commercial stocks"], ["Import and export flows", "UN Comtrade by HS code"], ["Major producing countries", "USGS / USDA / EIA"], ["Major consuming countries", "IEA / USDA / industry bodies"], ["Production costs", "Industry cost curves (often licensed)"], ["Futures curve", "Exchange settlement prices"], ["Shipping costs", "Baltic indices (licensed)"], ["Geopolitical exposure", "Producer concentration × risk"]];
  return header(pg, `${esc(c.name)} (${esc(c.unit)}), ${esc(c.group)}.`, { right: selectBox(pg, cs.map(x => [x.key, x.name]), c.key, "Commodity") }) + metaStrip(["yahoo"]) +
    (c.key === "gold" ? `<div class="note" style="margin-bottom:10px">Deep-dive: <a href="#/gold/overview">Gold Intelligence →</a></div>` : "") +
    (p ? `<div class="g g6">${kpi("Last", fmt(p.last, 2), `${esc(c.unit)} · ${esc(p.date)}`)}${kpi("1 month", pct(p.m1), "")}${kpi("1 year", pct(p.y1), `YTD ${pct(p.ytd)}`)}${kpi("Volatility 30d", fmt(p.vol30, 1) + "%", "")}${kpi("Max drawdown 1y", fmt(p.dd1y, 1) + "%", `52w ${fmt(p.lo52, 2)}–${fmt(p.hi52, 2)}`)}${kpi("Currency exposure", usdCorr != null ? sgn(usdCorr, 2) : "—", usdCorr != null ? `corr with dollar index, 250d · beta ${sgn(usdBeta, 2)}` : "not in matrix")}</div>` +
      panel("Price (2 years, front-month futures)", lineChart([{ name: c.name, dates: c.series.dates, values: c.series.values, color: C.gold }], { height: 240, area: true })) : `<div class="pending">No free daily price for ${esc(c.name)}. Planned source: ${esc(COM_SRC[c.group] || "")}.</div>`) +
    panel("Fundamentals", table([{ t: "Measure" }, { t: "Status" }, { t: "Planned source" }], pend.map(([a, b]) => [esc(a), PEND, `<span class="sm dim">${esc(b)}; ${esc(COM_SRC[c.group] || "")}</span>`]))); });
PAGES["commodities/fundamentals"] = pg => pendingPage(pg, { lede: "Production, consumption, inventories, trade flows, producers, consumers, costs, futures curves and shipping for every commodity.", what: "Each commodity has different official sources, most published monthly or annually.", fields: "balances, stocks-to-use, top producers/consumers, cost curves, curve shape (contango/backwardation), freight", source: "EIA, IEA, OPEC, USGS, USDA WASDE, FAO, ICSG, worldsteel; LME and Baltic Exchange data are licensed" });

/* ======================= MODULE 4: FISCAL ======================= */
