const fiscLines = (code, lab) => G_(pg => header(pg, `${lab}: history and IMF projections (dashed).`) + metaStrip(["imf"]) + `<div class="g g2">${CTRY().map(c => panel(esc(c.name), lineChart(yrSeries(GD().imf[code]?.[c.iso3], lab, C.gold), { height: 150, zero: true, unit: "%" }))).join("")}</div>`);
PAGES["fiscal/debt"] = G_(pg => header(pg, "Gross government debt and the fiscal balance, % of GDP. Dashed lines are IMF projections.") + metaStrip(["imf"]) +
  `<div class="g g2">${panel("Gross debt, % of GDP", lineChart(CTRY().flatMap((c, i) => yrSeries(GD().imf.GGXWDG_NGDP?.[c.iso3], c.name, [C.gold, C.s1, C.s2, C.s3, C.s4, C.s5, "#8fb8ef", "#e0c27e", "#a7abb3", "#f0a3a3"][i])), { height: 300, unit: "%" }))}${panel("Fiscal balance, % of GDP", lineChart(CTRY().flatMap((c, i) => yrSeries(GD().imf.GGXCNL_NGDP?.[c.iso3], c.name, [C.gold, C.s1, C.s2, C.s3, C.s4, C.s5, "#8fb8ef", "#e0c27e", "#a7abb3", "#f0a3a3"][i])), { height: 300, zero: true, unit: "%" }))}</div>`);
PAGES["fiscal/revenue"] = G_(pg => header(pg, "Government revenue and expenditure, % of GDP (IMF).") + metaStrip(["imf"]) + `<div class="g g2">${CTRY().map(c => panel(esc(c.name), lineChart([...yrSeries(GD().imf.GGR_NGDP?.[c.iso3], "Revenue", C.s1), ...yrSeries(GD().imf.GGX_NGDP?.[c.iso3], "Expenditure", C.s2)], { height: 160, unit: "%" }))).join("")}</div>`);
PAGES["fiscal/spending"] = G_(pg => header(pg, "Interest costs, defence, subsidies and taxes (World Bank, annual; latest year varies by country).") + metaStrip(["worldbank"]) +
  panel("Spending composition", table([{ t: "Country" }, { t: "Interest, % of revenue", n: 1 }, { t: "Defence, % of GDP", n: 1 }, { t: "Subsidies & transfers, % of expense", n: 1 }, { t: "Tax revenue, % of GDP", n: 1 }, { t: "Expense, % of GDP", n: 1 }], CTRY().map(c => [esc(c.name), ...["GC.XPN.INTP.RV.ZS", "MS.MIL.XPND.GD.ZS", "GC.XPN.TRFT.ZS", "GC.TAX.TOTL.GD.ZS", "GC.XPN.TOTL.GD.ZS"].map(k => fiscCell(wbL(k, c.iso3)))])), "", "flush") +
  `<div class="pending" style="margin-top:12px"><b>Pending:</b> infrastructure spending, fiscal stimulus packages and tax policy changes (national budgets, OECD tax database).</div>`);
PAGES["fiscal/sovereign-risk"] = G_(pg => { const g = GD();
  return header(pg, "Indicators of sovereign credit risk: debt, deficits, interest burden and bond yields. Credit ratings and CDS are licensed and not shown.") + metaStrip(["imf", "worldbank", "fred", "yahoo"]) +
    panel("Risk indicators", table([{ t: "Country" }, { t: "Debt % GDP", n: 1 }, { t: "Fiscal bal. % GDP", n: 1 }, { t: "Interest % revenue", n: 1 }, { t: "Curr. acct % GDP", n: 1 }, { t: "10y yield", n: 1 }, { t: "Rating / CDS" }], CTRY().map(c => [esc(c.name), fiscCell(imfL("GGXWDG_NGDP", c.iso3)), fiscCell(imfL("GGXCNL_NGDP", c.iso3)), fiscCell(wbL("GC.XPN.INTP.RV.ZS", c.iso3)), fiscCell(imfL("BCA_NGDPD", c.iso3)), c.key === "us" ? `<span class="num">${fmt(g.markets.yields.find(y => y.key === "us10y")?.perf?.last, 2)}%</span>` : g.fred?.[c.key] ? `<span class="num">${fmt(g.fred[c.key].latest.value, 2)}%</span><div class="sm dim">${esc(g.fred[c.key].latest.date)}</div>` : "—", `<span class="dim sm">licensed</span>`])), "", "flush"); });
PAGES["fiscal/country"] = G_(pg => { const c = cBy(pg.param) || CTRY()[0];
  return header(pg, `${esc(c.name)}: public finances, history and IMF projections.`, { right: selectBox(pg, CTRY().map(x => [x.key, x.name]), c.key, "Country") }) + metaStrip(["imf", "worldbank"]) +
    `<div class="g g3">${FISC.map(([k, t]) => panel(`${t}, % of GDP`, lineChart(yrSeries(GD().imf[k]?.[c.iso3], t, C.gold), { height: 170, zero: true, unit: "%" }))).join("")}</div>` +
    panel("World Bank detail", table(IND_COLS, [["GC.XPN.INTP.RV.ZS", "Interest payments, % of revenue"], ["MS.MIL.XPND.GD.ZS", "Military expenditure, % of GDP"], ["GC.XPN.TRFT.ZS", "Subsidies and transfers, % of expense"], ["GC.TAX.TOTL.GD.ZS", "Tax revenue, % of GDP"]].map(([k, l]) => { const v = wbL(k, c.iso3); return indRow(l, v?.value, "%", v?.year, "Actual", "World Bank"); }).concat([indRow("Debt maturity profile", null, "", "", "", "National debt office"), indRow("Bond issuance", null, "", "", "", "National debt office"), indRow("Foreign ownership of government debt", null, "", "", "", c.key === "us" ? "US Treasury TIC" : "National debt office / IMF")]))); });
PAGES["fiscal/debt-structure"] = pg => pendingPage(pg, { lede: "Debt maturity, issuance, ownership and foreign holdings.", what: "Each country publishes this through its debt management office in different formats.", fields: "average maturity, redemption profile, gross issuance, holder breakdown (central bank, banks, foreign), foreign share", source: "US Treasury (Fiscal Data API, TIC), UK DMO, Japan MoF, Germany Finanzagentur, France AFT, RBI, etc." });

/* ======================= MODULE 5: TRADE ======================= */
const TR = () => GD()?.trade || {};
PAGES["trade/overview"] = G_(pg => header(pg, "Exports, imports and balances: goods and services (World Bank) and goods by partner (UN Comtrade).") + metaStrip(["worldbank", "comtrade", "imf"]) +
  panel("Trade and current account", table([{ t: "Country" }, { t: "Exports (G&S)", n: 1 }, { t: "Imports (G&S)", n: 1 }, { t: "Trade balance", n: 1 }, { t: "Year" }, { t: "Current account % GDP", n: 1 }, { t: "Goods exports (Comtrade)", n: 1 }, { t: "Goods imports (Comtrade)", n: 1 }, { t: "Comtrade year" }], CTRY().map(c => { const t = TR().countries?.[c.key] || {};
    return [`<a href="#/trade/partners/${c.key}"><b>${esc(c.name)}</b></a>`, big(wbL("NE.EXP.GNFS.CD", c.iso3)?.value), big(wbL("NE.IMP.GNFS.CD", c.iso3)?.value), big(wbL("NE.RSB.GNFS.CD", c.iso3)?.value), wbL("NE.EXP.GNFS.CD", c.iso3)?.year ?? "", fiscCell(imfL("BCA_NGDPD", c.iso3)), big(t.exports?.total), big(t.imports?.total), t.exports?.year ?? (c.key === "ru" ? `<span class="sm dim">not reported since 2021</span>` : PEND)]; })), "", "flush") +
  panel("Trade balance, US$ bn (World Bank)", barChart(CTRY().map(c => c.name.replace("United ", "U. ")), CTRY().map(c => wbL("NE.RSB.GNFS.CD", c.iso3) ? wbL("NE.RSB.GNFS.CD", c.iso3).value / 1e9 : null), { diverging: true, height: 200, fmt: v => fmt(v, 0) })));
PAGES["trade/partners"] = G_(pg => { const c = cBy(pg.param) || CTRY()[0], t = TR().countries?.[c.key] || {};
  const pt = (x, lab) => x ? panel(`${lab}, ${x.year}: ${big(x.total)}`, table([{ t: "#", n: 1 }, { t: "Partner" }, { t: "Value", n: 1 }, { t: "Share", n: 1 }], x.partners.slice(0, 20).map((p, i) => [i + 1, esc(p.name), big(p.value), `<span class="num">${fmt(p.share, 1)}%</span>`])), "UN Comtrade", "flush") : panel(lab, `<div class="pending">${c.key === "ru" ? "Russia has not reported to UN Comtrade since 2021; mirror data (partners' reports) is the planned substitute." : "Not loaded in the latest run."}</div>`);
  return header(pg, `${esc(c.name)}: top 20 export destinations and import sources (goods).`, { right: selectBox(pg, CTRY().map(x => [x.key, x.name]), c.key, "Reporter") }) + metaStrip(["comtrade"]) + `<div class="g g2">${pt(t.exports, "Exports")}${pt(t.imports, "Imports")}</div>`; });
PAGES["trade/bilateral"] = G_(pg => { const m = TR().matrix;
  return header(pg, "Goods exports between the ten economies, US$ bn, as reported by the exporter.") + metaStrip(["comtrade"]) +
    (m ? panel("Bilateral export matrix (row exports to column)", matrixHeat(m.keys.map(k => cBy(k).name), m.keys.map(k => cBy(k).name), m.values_bn, { scale: Math.max(1, ...m.values_bn.flat().filter(v => v != null)), fmt: v => fmt(v, 0), left: 120 })) + `<div class="note">${esc(m.note)}</div>` : `<div class="pending">Trade matrix not loaded.</div>`); });
PAGES["trade/products"] = G_(pg => { const c = cBy(pg.param) || CTRY()[0], t = TR().countries?.[c.key] || {};
  const pt = (x, lab) => x ? panel(`${lab} by HS chapter, ${x.year}`, table([{ t: "HS" }, { t: "Product" }, { t: "Value", n: 1 }, { t: "Share", n: 1 }], x.top.map(p => [`<span class="mono">${esc(p.hs)}</span>`, `<span class="sm">${esc(p.desc)}</span>`, big(p.value), `<span class="num">${fmt(p.share, 1)}%</span>`])) + `<div class="note" style="padding:0 14px 10px">Concentration (HHI across HS chapters): <b class="num">${fmt(x.hhi, 0)}</b> (above 1,500 = concentrated).</div>`, "", "flush") : panel(lab, `<div class="pending">Not loaded.</div>`);
  return header(pg, `${esc(c.name)}: main exported and imported products and export concentration.`, { right: selectBox(pg, CTRY().map(x => [x.key, x.name]), c.key, "Country") }) + metaStrip(["comtrade"]) + `<div class="g g2">${pt(t.exports_products, "Exports")}${pt(t.imports_products, "Imports")}</div>`; });
PAGES["trade/dependency"] = G_(pg => { const groups = Object.keys(Object.values(TR().countries || {}).find(x => x.imports_products)?.imports_products?.groups || {});
  const mat = f => CTRY().map(c => groups.map(g => TR().countries?.[c.key]?.[f]?.groups?.[g] ?? null));
  return header(pg, "Strategic dependencies: share of each economy's goods imports and exports in critical categories.") + metaStrip(["comtrade", "worldbank"]) +
    (groups.length ? panel("Import dependency, % of goods imports", matrixHeat(CTRY().map(c => c.name), groups.map(g => g.replace(/ \(.+\)/, "")), mat("imports_products"), { scale: 40, fmt: v => fmt(v, 1), left: 120, top: 110 })) + panel("Export reliance, % of goods exports", matrixHeat(CTRY().map(c => c.name), groups.map(g => g.replace(/ \(.+\)/, "")), mat("exports_products"), { scale: 40, fmt: v => fmt(v, 1), left: 120, top: 110 })) : `<div class="pending">Product data not loaded.</div>`) +
    `<div class="pending" style="margin-top:12px"><b>Pending:</b> which partner supplies each category (e.g. who supplies India's energy, Germany's semiconductors). This needs partner-by-product queries (HS 27, 26/72–81, 01–24, 84, 85, 8541–8542, 30), planned with a free Comtrade API key. Semiconductors sit inside HS 85 at chapter level.</div>`; });
PAGES["trade/tariffs"] = G_(pg => header(pg, "Applied tariff rates (World Bank, trade-weighted mean, all products).") + metaStrip(["worldbank"]) +
  panel("Tariffs", table(IND_COLS, CTRY().map(c => { const v = wbL("TM.TAX.MRCH.WM.AR.ZS", c.iso3); return indRow(c.name, v?.value, "%", v?.year, "Actual", "World Bank / WITS"); })), "", "flush") +
  `<div class="pending" style="margin-top:12px"><b>Pending:</b> current tariff actions, sanctions and export controls (WTO tariff database, national gazettes). 2025–2026 US tariff changes are not reflected in the World Bank series until it updates.</div>`);

/* ======================= MODULE 6: CAPITAL FLOWS ======================= */
PAGES["flows/overview"] = G_(pg => header(pg, "Cross-border investment flows from the balance of payments (World Bank, annual, US$). Flows are what moved in a year; positions are stocks held.") + metaStrip(["worldbank"]) +
  panel("Investment flows, latest year", table([{ t: "Country" }, { t: "FDI net inflows", n: 1 }, { t: "FDI net outflows", n: 1 }, { t: "Portfolio equity net inflows", n: 1 }, { t: "Year" }], CTRY().map(c => [esc(c.name), big(wbL("BX.KLT.DINV.CD.WD", c.iso3)?.value), big(wbL("BM.KLT.DINV.CD.WD", c.iso3)?.value), big(wbL("BX.PEF.TOTL.CD.WD", c.iso3)?.value), wbL("BX.KLT.DINV.CD.WD", c.iso3)?.year ?? ""])), "", "flush") +
  `<div class="g g2" style="margin-top:12px">${CTRY().slice(0, 4).map(c => { const d = GD().wb["BX.KLT.DINV.CD.WD"]?.[c.iso3]; return panel(`${esc(c.name)}: FDI net inflows, US$ bn`, d ? barChart(d.series.years.map(String), d.series.values.map(v => v / 1e9), { diverging: true, height: 150, fmt: v => fmt(v, 0) }) : PEND); }).join("")}</div>`);
// demonstration dataset (synthetic, clearly labelled) for the map component
const DEMO_INV = (() => { const keys = ["us", "cn", "jp", "de", "fr", "in", "gb", "ca", "ch", "ru"]; let seed = 7; const r = () => (seed = (seed * 9301 + 49297) % 233280) / 233280;
  return keys.map(a => keys.map(b => a === b ? null : Math.round(r() * 100))); })();
function invMap(focus, mode) {
  const keys = CTRY().map(c => c.key), id = uid(), fi = keys.indexOf(focus);
  mount(() => { const el = document.getElementById(id); if (!el) return; const W = Math.max(520, el.clientWidth), H = 360, cx = W / 2, cy = H / 2, R0 = 135;
    const pos = keys.map((k, i) => { const a = -Math.PI / 2 + i * 2 * Math.PI / keys.length; return [cx + R0 * Math.cos(a), cy + R0 * Math.sin(a)]; });
    let svg = `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Investment map (demonstration data)"><text x="${W / 2}" y="${H / 2 + 6}" text-anchor="middle" style="font-size:28px;fill:rgba(201,133,0,.14);font-weight:600">DEMO DATA</text>`;
    keys.forEach((k, j) => { if (j === fi) return; const v = mode === "investor" ? DEMO_INV[fi][j] : DEMO_INV[j][fi]; const [x1, y1] = mode === "investor" ? pos[fi] : pos[j], [x2, y2] = mode === "investor" ? pos[j] : pos[fi];
      svg += `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#c98500" stroke-opacity=".55" stroke-width="${1 + v / 18}"/>`; });
    keys.forEach((k, i) => { const [x, y] = pos[i]; svg += `<circle cx="${x}" cy="${y}" r="${i === fi ? 9 : 6}" fill="${i === fi ? C.gold : "#2b3038"}" stroke="#c6a052"/><text x="${x}" y="${y + (y < cy ? -14 : 22)}" text-anchor="middle" style="fill:${C.ink2}">${esc(cBy(k).name)}</text>`; });
    el.innerHTML = svg + "</svg>"; });
  return `<div class="chart" id="${id}"></div>`;
}
const invPage = mode => G_(pg => { const focus = pg.param || "us", c = cBy(focus), keys = CTRY().map(x => x.key), fi = keys.indexOf(focus);
  const rows = keys.map((k, j) => [cBy(k).name, mode === "investor" ? DEMO_INV[fi][j] : DEMO_INV[j][fi]]).filter(r => r[1] != null).sort((a, b) => b[1] - a[1]);
  return header(pg, mode === "investor" ? `Where does ${esc(c.name)} invest? Select an investor country.` : `Who invests in ${esc(c.name)}? Select a destination country.`, { right: selectBox(pg, CTRY().map(x => [x.key, x.name]), focus, mode === "investor" ? "Investor" : "Destination") }) + DEMO_BANNER +
    `<div class="g g-21">${panel(`World investment map (DEMO)`, invMap(focus, mode))}${panel(mode === "investor" ? "Destinations (DEMO index)" : "Investors (DEMO index)", table([{ t: "Country" }, { t: "Demo value", n: 1 }], rows.map(r => [esc(r[0]), `<span class="num" style="color:#e0c27e">${r[1]} (demo)</span>`])))}</div>` +
    panel("When real data is connected", `<ul class="clean"><li><b>Positions</b> (stocks): IMF Coordinated Direct Investment Survey (CDIS) and Portfolio Investment Survey (CPIS), annual, bilateral.</li><li><b>Flows</b>: OECD FDI statistics by partner; national balance-of-payments releases.</li><li><b>Announced vs completed</b>: greenfield project announcements (e.g. fDi Markets, licensed) are kept separate from completed transactions and official statistics.</li></ul>`); });
PAGES["flows/map"] = invPage("investor"); PAGES["flows/investor"] = invPage("investor"); PAGES["flows/destination"] = invPage("destination");
PAGES["flows/positions"] = G_(pg => header(pg, "Flows and positions are different measures and are never mixed on SOVEREIGN pages.") +
  `<div class="g g2">${panel("Flows (what moved during a period)", `<ul class="clean"><li>Balance-of-payments FDI and portfolio flows, annual: <b>connected</b> (World Bank).</li><li>Monthly portfolio flows (e.g. US TIC, Japan MoF weekly): pending.</li></ul>`)}${panel("Positions (what is held at a date)", `<ul class="clean"><li>International investment positions (IMF IIP): pending.</li><li>Bilateral direct and portfolio positions (IMF CDIS, CPIS): pending.</li><li>Foreign holdings of government bonds (US TIC, national debt offices): pending.</li></ul>`)}</div>` +
  panel("Announced vs completed", `<p class="sm" style="margin:0">Announced greenfield projects and M&A deals are intentions; completed investment shows up later in official flow data. When integrated, announced items will carry an "Announced" label and will not be added to official flows.</p>`));
PAGES["flows/institutions"] = pg => pendingPage(pg, { lede: "Sovereign wealth funds, pension funds and other large institutions.", what: "Holdings come from fund annual reports and regulatory filings (e.g. Norway GPFG publishes all holdings; US 13F).", fields: "assets under management, allocation by country and asset class, largest holdings, changes", source: "Fund annual reports (NBIM, GIC, ADIA, CPP, GPIF), SEC 13F" });
PAGES["flows/banking"] = pg => pendingPage(pg, { lede: "International banking assets and cross-border lending.", what: "BIS locational and consolidated banking statistics are free but not yet integrated.", fields: "cross-border claims by creditor and borrower country, foreign claims, currency breakdown", source: "BIS Locational Banking Statistics (WS_LBS_D_PUB), Consolidated Banking Statistics (WS_CBS_PUB)" });

/* ======================= MODULE 7: CORPORATES ======================= */
const CF = [["revenue", "Revenue"], ["ebitda", "EBITDA"], ["ebit", "EBIT"], ["net_income", "Net income"], ["assets", "Total assets"], ["liabilities", "Total liabilities"], ["equity", "Equity"], ["cash", "Cash"], ["debt", "Long-term debt"], ["ocf", "Operating cash flow"], ["fcf", "Free cash flow"], ["capex", "Capital expenditure"], ["acquisitions", "Acquisitions (cash paid)"], ["investments", "Purchases of investments"], ["divestments", "Divestment proceeds"], ["public_float", "Public float (proxy for market value)"]];
const edgar = c => `https://www.sec.gov/cgi-bin/browse-edgar?action=getcompany&CIK=${c.cik}&type=10-K`;
PAGES["corporate/database"] = G_(pg => { const cs = GD().companies || [];
  const v = (c, f) => c.fields[f] ? big(c.fields[f].value) : "—";
  return header(pg, "Listed companies with figures taken directly from regulatory filings. Coverage is shown, not padded.") + metaStrip(["sec"]) +
    `<div class="g g4">${kpi("Companies with data", cs.length, "United States (SEC XBRL)")}${kpi("Target", "500 per country", "10 countries")}${kpi("Countries covered", cs.length ? "1 of 10" : "0 of 10", "")}${kpi("Coverage", fmt(cs.length / 5000 * 100, 1) + "%", "of the 5,000-company target")}</div>` +
    panel("Corporate database", cs.length ? table([{ t: "Company" }, { t: "Country" }, { t: "FY end" }, { t: "Revenue", n: 1 }, { t: "Rev. YoY", n: 1 }, { t: "EBIT", n: 1 }, { t: "Net income", n: 1 }, { t: "Total assets", n: 1 }, { t: "Cash", n: 1 }, { t: "LT debt", n: 1 }, { t: "FCF", n: 1 }, { t: "Capex", n: 1 }, { t: "Acquisitions", n: 1 }], cs.slice().sort((a, b) => (b.fields.revenue?.value || 0) - (a.fields.revenue?.value || 0)).map(c => { const r = c.fields.revenue;
      return [`<a href="#/corporate/company/${c.cik}"><b>${esc(c.listed_name || c.name)}</b></a><div class="sm dim">${esc(c.name)}</div>`, "US", esc(r?.period_end || "—"), v(c, "revenue"), r?.prev ? pct((r.value / r.prev - 1) * 100, 1) : "—", v(c, "ebit"), v(c, "net_income"), v(c, "assets"), v(c, "cash"), v(c, "debt"), v(c, "fcf"), v(c, "capex"), v(c, "acquisitions")]; }), { max: 620 }) : `<div class="pending">No company data in the latest run.</div>`, "latest 10-K per company", "flush"); });
PAGES["corporate/company"] = G_(pg => { const cs = GD().companies || []; if (!cs.length) return header(pg) + `<div class="pending">No company data.</div>`;
  const c = cs.find(x => String(x.cik) === pg.param) || cs[0];
  return header(pg, `${esc(c.name)}: annual figures from SEC filings, with reporting period and filing for every number.`, { right: selectBox(pg, cs.map(x => [String(x.cik), x.listed_name || x.name]), String(c.cik), "Company") }) + metaStrip(["sec"]) +
    panel("Financials (latest fiscal year)", table([{ t: "Measure" }, { t: "Latest", n: 1 }, { t: "Prior year", n: 1 }, { t: "YoY", n: 1 }, { t: "Period end" }, { t: "Filing" }, { t: "Basis" }], CF.map(([k, l]) => { const f = c.fields[k];
      return f ? [esc(l), `<b class="num">${big(f.value)}</b>`, f.prev != null ? big(f.prev) : "—", f.prev ? pct((f.value / f.prev - 1) * 100, 1) : "—", esc(f.period_end), `<span class="sm">${esc(f.form || "")} filed ${esc(f.filed || "")}</span>`, `<span class="sm dim">${f.derived ? "Derived: " + esc(f.derived) : "XBRL " + esc(f.tag || "")}</span>`] : [esc(l), "—", "", "", "", "", PEND]; })) + `<div class="note">Source: <a href="${edgar(c)}" target="_blank" rel="noopener">SEC EDGAR filings for CIK ${c.cik}</a>. Public float is the value held by non-affiliates at the filer's mid-year date, not market capitalisation.</div>`) +
    `<div style="margin-top:12px">${panel("International footprint", table([{ t: "Item" }, { t: "Status" }, { t: "Note" }], [["Geographic revenue", "Revenue by region is disclosed in segment notes; parsing pending.", "Revenue location is not investment location."], ["Foreign subsidiaries", "Exhibit 21 (list of subsidiaries) parsing pending.", ""], ["Foreign acquisitions", "Total acquisition spend shown above; country breakdown needs filing text.", ""], ["Long-lived assets by country", "Segment-note parsing pending.", "Best evidence of where capital is invested."], ["Strategic investments and divestments", "Totals above; deal-level detail pending.", ""]].map(r => [esc(r[0]), `<span class="sm">${esc(r[1])}</span>`, `<span class="sm dim">${esc(r[2])}</span>`])))}</div>`; });
PAGES["corporate/coverage"] = G_(pg => { const cs = GD().companies || [], src = GD().company_sources || {};
  return header(pg, "Coverage of the corporate database by country. Target: up to 500 largest listed companies per country.") + metaStrip(["sec"]) +
    panel("Coverage", table([{ t: "Country" }, { t: "Records", n: 1 }, { t: "Target", n: 1 }, { t: "Coverage", n: 1 }, { t: "Source" }, { t: "Status" }], CTRY().map(c => { const n = cs.filter(x => x.country === c.key).length;
      return [esc(c.name), `<span class="num">${n}</span>`, "500", `<span class="num">${fmt(n / 5, 1)}%</span>`, `<span class="sm">${esc(src[c.key] || "")}</span>`, n ? statusPill("Fair").replace(">Fair<", ">Partial<") : PEND]; }))) +
    `<div class="note">Companies are added only when their figures can be taken from a filing. Nothing is estimated to fill the table.</div>`; });
PAGES["corporate/exposure"] = G_(pg => { const cs = GD().companies || [];
  const tot = f => cs.reduce((s, c) => s + (c.fields[f]?.value || 0), 0);
  return header(pg, "Where do major corporations invest their capital? This report separates six different things that are often confused.") + metaStrip(["sec"]) +
    panel("Six measures, never mixed", table([{ t: "Measure" }, { t: "What it shows" }, { t: "Is it investment in that country?" }, { t: "Status" }], [
      ["Geographic revenue", "Where customers are", "No", "Pending (segment notes)"], ["Foreign assets (long-lived)", "Where plants, property and equipment sit", "Yes, closest proxy", "Pending (segment notes)"],
      ["Direct investments", "Ownership of foreign subsidiaries and affiliates", "Yes", "Pending (Exhibit 21, notes)"], ["Portfolio holdings", "Financial securities held", "Financial, not operating", "Totals connected"],
      ["Acquisitions", "Companies bought", "Yes, by target location", "Totals connected; country pending"], ["Capital expenditure", "Spending on new assets", "Yes, by location of spend", "Totals connected; country pending"]].map(r => r.map(esc)))) +
    `<div class="g g3" style="margin-top:12px">${kpi("Capex, covered US companies", big(tot("capex")), `${cs.length} companies, latest fiscal year`)}${kpi("Acquisitions paid", big(tot("acquisitions")), "all locations")}${kpi("Purchases of investments", big(tot("investments")), "all locations")}</div>` +
    `<div class="pending"><b>Country-to-country corporate investment</b> needs geographic segment and subsidiary data, which is parsed from filing text. Until then these totals are not split by destination.</div>`; });
PAGES["corporate/country-reports"] = G_(pg => { const cs = GD().companies || [];
  return header(pg, "Reports by home country: how companies from one country invest abroad.") + metaStrip(["sec"]) +
    `<div class="g g2">${[["us", "US corporations investing internationally"], ["cn", "Chinese corporations investing internationally"], ["jp", "Japanese corporations investing internationally"], ["de", "German corporations investing internationally"], ["in", "Indian corporations investing internationally"]].map(([k, t]) => panel(esc(t), k === "us" && cs.length ? `<p class="sm">${cs.length} US companies loaded. Combined latest-year capex <b>${big(cs.reduce((s, c) => s + (c.fields.capex?.value || 0), 0))}</b>, acquisitions <b>${big(cs.reduce((s, c) => s + (c.fields.acquisitions?.value || 0), 0))}</b>. Destination split pending.</p>` : `<div class="pending sm">No companies loaded for this country yet. Source: ${esc(GD().company_sources?.[k] || "")}.</div>`)).join("")}</div>`; });
PAGES["institutional/company-financials"] = PAGES["corporate/database"]; PAGES["institutional/balance-sheets"] = PAGES["corporate/database"];

/* ======================= MODULE 9: CREDIT ======================= */
const CRED = [["FS.AST.PRVT.GD.ZS", "Private credit, % of GDP"], ["FB.AST.NPER.ZS", "Non-performing loans, %"], ["FB.BNK.CAPA.ZS", "Bank capital to assets, %"], ["FD.RES.LIQU.AS.ZS", "Liquid reserves to assets, %"], ["FR.INR.LEND", "Lending rate, %"], ["FM.LBL.BMNY.ZG", "Broad money growth, %"]];
PAGES["credit/overview"] = G_(pg => header(pg, "Credit and banking indicators (World Bank, annual). Latest year differs by country and indicator.") + metaStrip(["worldbank"]) +
  panel("Credit and banking", table([{ t: "Country" }, ...CRED.map(([, l]) => ({ t: l, n: 1 }))], CTRY().map(c => [esc(c.name), ...CRED.map(([k]) => fiscCell(wbL(k, c.iso3)))])), "", "flush") +
  `<div class="pending" style="margin-top:12px"><b>Pending:</b> household and corporate debt (BIS total credit statistics), deposit growth and bank lending (national central banks), banking system assets.</div>`);
PAGES["credit/private-credit"] = G_(pg => header(pg, "Domestic credit to the private sector, % of GDP. Rapid credit growth above trend has preceded banking stress historically.") + metaStrip(["worldbank"]) +
  panel("Private credit, % of GDP", lineChart(CTRY().map((c, i) => { const d = GD().wb["FS.AST.PRVT.GD.ZS"]?.[c.iso3]; return d ? { name: c.name, dates: d.series.years.map(y => `${y}-07-01`), values: d.series.values, color: [C.gold, C.s1, C.s2, C.s3, C.s4, C.s5, "#8fb8ef", "#e0c27e", "#a7abb3", "#f0a3a3"][i] } : null; }).filter(Boolean), { height: 300, unit: "%" })));
PAGES["credit/banks"] = G_(pg => header(pg, "Bank asset quality, capital and liquidity (World Bank / IMF Financial Soundness Indicators).") + metaStrip(["worldbank"]) +
  `<div class="g g3">${[["FB.AST.NPER.ZS", "Non-performing loans, % of gross loans"], ["FB.BNK.CAPA.ZS", "Bank capital to assets, %"], ["FD.RES.LIQU.AS.ZS", "Liquid reserves to assets, %"]].map(([k, l]) => panel(esc(l), barChart(CTRY().map(c => c.name.replace("United ", "U. ")), CTRY().map(c => wbL(k, c.iso3)?.value ?? null), { height: 190, fmt: v => fmt(v, 1), color: C.s1 }))).join("")}</div>`);
PAGES["credit/spreads"] = G_(pg => { const f = GD().fred || {}, hy = f.hy_oas, ig = f.ig_oas, px = GD().markets.proxies;
  return header(pg, "Corporate credit spreads and high-yield markets.") + metaStrip(["fred", "yahoo"]) +
    (hy || ig ? panel("US option-adjusted spreads (ICE BofA, %)", lineChart([hy && { name: "High yield", dates: hy.series.dates, values: hy.series.values, color: C.bear }, ig && { name: "Investment grade", dates: ig.series.dates, values: ig.series.values, color: C.s1 }].filter(Boolean), { height: 240, unit: "%" })) : `<div class="pending">Spread series need the FRED key.</div>`) +
    panel("Credit ETF performance (proxies)", table([{ t: "Instrument" }, ...PERF_COLS], px.filter(p => ["hyg", "lqd", "tlt"].includes(p.key)).map(p => [esc(p.name), ...perfCells(p.perf)]))); });
PAGES["credit/stress"] = G_(pg => { const flag = (v, hi, lo) => v == null ? "" : (hi != null && v > hi) || (lo != null && v < lo) ? `<span class="pill crit">Watch</span>` : `<span class="pill good">OK</span>`;
  return header(pg, "Simple banking stress flags. Thresholds are rules of thumb, shown so they can be checked, not scientific cut-offs.") + metaStrip(["worldbank"]) +
    panel("Stress indicators", table([{ t: "Country" }, { t: "NPLs %", n: 1 }, { t: "Flag (> 5%)" }, { t: "Capital/assets %", n: 1 }, { t: "Flag (< 6%)" }, { t: "Private credit % GDP", n: 1 }, { t: "Flag (> 150%)" }], CTRY().map(c => { const n = wbL("FB.AST.NPER.ZS", c.iso3), k = wbL("FB.BNK.CAPA.ZS", c.iso3), p = wbL("FS.AST.PRVT.GD.ZS", c.iso3);
      return [esc(c.name), fiscCell(n), flag(n?.value, 5), fiscCell(k), flag(k?.value, null, 6), fiscCell(p), flag(p?.value, 150)]; })), "", "flush"); });

/* ======================= MODULE 10: RELATIONSHIP ENGINE ======================= */
PAGES["relationships/overview"] = G_(pg => header(pg, "How developments in one place travel to others. Each report separates the mechanism (interpretation) from the evidence (computed from data) and lists what contradicts it.") +
  `<div class="g g2">${(GD().reports || []).map(r => panel(`<a href="#/relationships/${r.key}">${esc(r.title)}</a>`, `<p class="sm" style="margin:0 0 6px">${esc(r.development)}</p><div class="sm dim">${r.evidence.length} evidence items · ${r.contradicting.length} contradicting · ${r.precedents.length} precedents</div>`)).join("")}</div>` +
  `<div class="note">Mechanisms, precedents and scenarios are AI interpretation and are labelled as such. Correlations and figures are computed from the sources shown. Historical relationships are not assumed to be permanent or causal.</div>`);
function reportPage(key) { return G_(pg => { const r = (GD().reports || []).find(x => x.key === key); if (!r) return header(pg) + `<div class="pending">Report not built.</div>`;
  return header(pg, esc(r.title)) + `<div class="g g4">${kpi("Development", "", esc(r.development))}${kpi("Evidence items", r.evidence.length, "computed")}${kpi("Contradicting", r.contradicting.length, "")}${kpi("Class", "", esc(r["class"]))}</div>` +
    `<div class="g g2">${panel("1–2. Development and transmission mechanism", `<p><b>${esc(r.development)}</b></p><ol class="clean" style="padding-left:18px">${r.mechanism.map(m => `<li>${esc(m)}</li>`).join("")}</ol>`, "AI interpretation")}
      ${panel("3–5. Who and what is affected", `<h3>Countries</h3>${listOr(r.countries)}<h3 style="margin-top:8px">Industries</h3>${listOr(r.industries)}<h3 style="margin-top:8px">Asset classes</h3>${listOr(r.assets)}`, "AI interpretation")}</div>
    <div class="g g3">${panel("6. Historical precedents", r.precedents.map(p => `<div style="margin-bottom:8px"><b>${esc(p.period)}</b><div class="sm">${esc(p.text)}</div></div>`).join(""), "AI interpretation")}${panel("7. Current supporting evidence", listOr(r.evidence, "None computed."), "computed")}${panel("8. Contradicting evidence", listOr(r.contradicting, "None found."), "computed / noted")}</div>` +
    panel("9. Possible scenarios", table([{ t: "Scenario" }, { t: "Historically associated with" }], r.scenarios.map(s => [`<b>${esc(s.name)}</b>`, esc(s.text)])) + `<div class="note">Scenarios describe conditional associations, not forecasts or probabilities.</div>`) +
    (r.link ? `<div class="note">Related: <a href="#/${esc(r.link)}">${esc(r.link)} →</a></div>` : ""); }); }
["usd-commodities", "real-yields-gold", "china-copper", "japan-tightening", "europe-germany", "oil-india", "us-deficit", "fdi-currency"].forEach(k => { PAGES[`relationships/${k}`] = reportPage(k); });
PAGES["relationships/explorer"] = G_(pg => { const m = GD().matrix; const [d, a] = (pg.param || "0-0").split("-").map(Number);
  const dn = m.drivers?.[d], an = m.assets?.[a]; const roll = dn === "USD (DXY)" ? m.rolling_usd?.[an] : null;
  const opts = []; (m.drivers || []).forEach((x, i) => (m.assets || []).forEach((y, j) => opts.push([`${i}-${j}`, `${x} → ${y}`])));
  return header(pg, "Pick a driver and an asset to see how they have moved together.", { right: selectBox(pg, opts, `${d}-${a}`, "Pair") }) + metaStrip(["yahoo"]) +
    (dn ? `<div class="g g3">${kpi("Correlation, 90 days", sgn(m.corr90[d][a], 2), "daily returns")}${kpi("Correlation, 250 days", sgn(m.corr250[d][a], 2), "")}${kpi("Beta, 250 days", sgn(m.beta250[d][a], 2), `% move in ${esc(an)} per 1% move in ${esc(dn)}`)}</div>` +
      (roll ? panel("Rolling 250-day correlation", lineChart([{ name: `${dn} vs ${an}`, dates: roll.dates, values: roll.values, color: C.gold }], { height: 220, zero: true, fmt: v => fmt(v, 2) })) : `<div class="note">Rolling history is computed for the dollar index against gold, oil, copper and emerging markets.</div>`) : `<div class="pending">Matrix not built.</div>`) +
    `<div class="note">A correlation describes co-movement in the sample only. It is not evidence of cause and can reverse.</div>`; });

/* ======================= MODULE 12: COVERAGE ======================= */
PAGES["platform/coverage"] = G_(pg => { const g = GD(), cv = g.coverage, errs = Object.entries(g.errors || {});
  const row = (m, have, tgt, note) => [esc(m), `<span class="num">${have}</span>`, `<span class="num">${tgt}</span>`, `<span class="num">${tgt ? fmt(have / tgt * 100, 0) + "%" : "—"}</span>`, `<span class="sm dim">${esc(note)}</span>`];
  return header(pg, "What SOVEREIGN covers today, where every number comes from, and what is still missing. Missing data is never filled with estimates or zeros.") +
    panel("Coverage achieved", table([{ t: "Module" }, { t: "Available", n: 1 }, { t: "Target", n: 1 }, { t: "Coverage", n: 1 }, { t: "Note" }], [
      row("Equity indices (prices)", cv.indices.covered, cv.indices.target, "valuation and composition pending"), row("Commodities (prices)", cv.commodities.priced, cv.commodities.target, "fundamentals pending"),
      row("Currencies", cv.currencies.covered, cv.currencies.target, ""), row("Central bank policy rates", cv.policy_rates.covered, cv.policy_rates.target, "Germany and France share the ECB"),
      row("World Bank indicators", cv.worldbank.indicators, cv.worldbank.target, `${cv.worldbank.country_cells} country-indicator series`), row("IMF WEO indicators", cv.imf.indicators, cv.imf.target, "includes projections, labelled"),
      row("Trade reporters (UN Comtrade)", cv.trade.reporters, cv.trade.target, "Russia not reporting since 2021"), row("Companies (filings)", cv.companies.records, cv.companies.target_per_country * cv.companies.countries, "US only so far"),
      row("Bilateral investment positions", 0, 100, "demo data only"), row("PMIs, confidence, retail sales", 0, 10, "licensed or not yet integrated")])) +
    `<div style="height:12px"></div>` + metaStrip(Object.keys(g.meta)).replace("<details", "<details open") +
    panel(`Source errors in the latest build (${errs.length})`, errs.length ? table([{ t: "Series" }, { t: "Error" }], errs.slice(0, 120).map(([k, v]) => [`<span class="mono sm">${esc(k)}</span>`, `<span class="sm">${esc(v)}</span>`]), { max: 400 }) : "None.") +
    panel("Rules", `<ul class="clean"><li>Missing data is shown as "—" or "pending", never as zero or an estimate.</li><li>Quarterly and annual data always shows its period; it is never labelled as current daily data.</li><li>IMF values for the current and future years are labelled as projections.</li><li>Demonstration data appears only on the investment map pages and is marked on every value.</li><li>Every stored value keeps the date the platform first saw it, so revisions are recorded.</li></ul>`); });

boot();
